tasks.setup:
const reqPerSec = 1000;
const bytesPerReq = 1024;
const services = 50;
const ingestPerGB = 0.10;
const secPerDay = 86400;
const gbPerServiceDay = (reqPerSec * bytesPerReq * secPerDay) / 1e9;
const fleetGBDay = gbPerServiceDay * services;
const rawMonthly = fleetGBDay * 30 * ingestPerGB;
const infoSampleRate = 0.01; // 1% of success-path INFO kept
const sampledFleetGBDay = fleetGBDay * infoSampleRate;
const sampledMonthly = sampledFleetGBDay * 30 * ingestPerGB;
console.log('GB/day per service:', gbPerServiceDay.toFixed(0));
console.log('Fleet GB/day (raw):', fleetGBDay.toFixed(0));
console.log('Raw monthly ingest $:', rawMonthly.toFixed(0));
console.log('Sampled monthly ingest $:', sampledMonthly.toFixed(0));

